static const FontData orbitronLarge150 = {orbitronLarge150Glyphs, orbitronLarge150Alpha, 32, 95, 20, 25};

static const FontSet fontSets[] = {
    {100, {&orbitronSmall100, &orbitronTitle100, &orbitronLarge100}},
    {150, {&orbitronSmall150, &orbitronTitle150, &orbitronLarge150}},
};

const FontSet& fontSetFor(int scalePercent) {
    const FontSet* best = &fontSets[0];
    for (const FontSet& set : fontSets) {
        int d = set.scalePercent - scalePercent, bd = best->scalePercent - scalePercent;
        if (d * d < bd * bd) best = &set;
    }
    return *best;
}
